begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into private.integration_settings(key,value) values('google_sheets_webhook_url','https://example.invalid/email-test'),('google_sheets_webhook_secret','local-test-only') on conflict(key) do update set value=excluded.value;
insert into auth.users(id,email) values('86000000-0000-4000-8000-000000000001','email-test@example.invalid');
insert into public.profiles(id,full_name,role,phone) values('86000000-0000-4000-8000-000000000001','Test admin','admin','0900099999') on conflict(id) do update set role='admin',phone=excluded.phone;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values('86000000-0000-4000-8000-000000000002','86000000-0000-4000-8000-000000000001','totp','verified','LOCAL-TEST-ONLY',now(),now());
insert into auth.users(id,email) values('86000000-0000-4000-8000-000000000003','guest@example.invalid');
insert into public.profiles(id,full_name,phone,email) values('86000000-0000-4000-8000-000000000003','Email Guest','0900000001','guest@example.invalid') on conflict(id) do update set full_name=excluded.full_name,phone=excluded.phone,email=excluded.email;
create temp table email_bookings(venue text,result jsonb);
grant all on email_bookings to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"86000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
insert into email_bookings select venue,public.staff_create_booking(jsonb_build_object('p_customer_id','86000000-0000-4000-8000-000000000003','p_booking_kind','event','p_duration_minutes',30,'p_allow_outside_hours',true,'p_booking_date',current_date+301,'p_booking_time','16:30','p_players_count',4,'p_arena_id',arena,'p_order_status','confirmed','p_customer_name','Email Guest','p_customer_phone','0900000001','p_customer_email','guest@example.invalid','p_internal_note','Original note'),source)
from (values('ha-do-centrosa','arena-1','walk_in'),('cafe-des-stagiaires','cafe:arena-1','phone')) v(venue,arena,source);
reset role;
select is((select count(*)::int from net.http_request_queue where url='https://example.invalid/email-test'),0,'No notification before transaction is complete');
set constraints all immediate;
select is((select count(*)::int from net.http_request_queue where url='https://example.invalid/email-test'),2,'Exactly one creation notification per venue after all order changes');
create temp view email_payloads as select convert_from(body,'UTF8')::jsonb as payload from net.http_request_queue where url='https://example.invalid/email-test';
select is((select payload#>>'{order,booking_source}' from email_payloads where payload#>>'{session,venue_key}'='ha-do-centrosa'),'walk_in','Ha Do receives final selected source');
select is((select payload#>>'{order,booking_source}' from email_payloads where payload#>>'{session,venue_key}'='cafe-des-stagiaires'),'phone','Thao Dien receives final selected source');
select is((select count(*)::int from email_payloads where payload->>'event_type'='ticket_booked'),2,'Creation remains creation despite intermediate updates');
select is((select count(*)::int from email_payloads where payload#>>'{customer,email}'='guest@example.invalid'),2,'Saved customer contact is used');
select is((select count(*)::int from email_payloads where payload#>>'{session,notes}' like '%Original note%'),2,'Internal order notes included for staff template');
delete from net.http_request_queue where url='https://example.invalid/email-test';
set constraints all deferred;
update public.sessions set notes=null where id in(select (result->>'session_id')::uuid from email_bookings);
update public.staff_orders set customer_email='changed@example.invalid',customer_phone='0900000002',customer_name='Changed name',booking_source='zalo',internal_note=null,total=0 where id in(select (result->>'order_id')::uuid from email_bookings);
set constraints all immediate;
select is((select count(*)::int from email_payloads),2,'Order-only changes notify both venues once');
select is((select count(*)::int from email_payloads where payload#>>'{previous_customer,email}'='guest@example.invalid' and payload#>>'{customer,email}'='changed@example.invalid'),2,'Both old and new email captured');
select is((select count(*)::int from email_payloads where payload#>>'{previous_customer,phone}'='0900000001' and payload#>>'{customer,phone}'='0900000002'),2,'Both old and new phone captured');
select is((select count(*)::int from email_payloads where payload#>>'{previous_customer,name}'='Email Guest' and payload#>>'{customer,name}'='Changed name'),2,'Both old and new name captured');
select is((select count(*)::int from email_payloads where payload#>>'{order,total}'='0'),2,'Zero total is retained');
select is((select count(*)::int from email_payloads where payload#>>'{order,booking_source}'='zalo'),2,'Explicit source changes captured');
select is((select count(*)::int from email_payloads where payload#>>'{previous_session,notes}' like '%Original note%' and payload#>>'{session,notes}' is null),2,'Note removal retains old value');
delete from net.http_request_queue where url='https://example.invalid/email-test';
set constraints all deferred;
update public.sessions set notes='New note',start_time='17:30',ticket_player_count=6,max_players=6 where id in(select (result->>'session_id')::uuid from email_bookings);
update public.staff_orders set booking_time='17:30',players_count=6 where id in(select (result->>'order_id')::uuid from email_bookings);
set constraints all immediate;
select is((select count(*)::int from email_payloads),2,'Session plus order changes produce one modification each');
select is((select count(*)::int from email_payloads where payload#>>'{previous_order,booking_source}'='zalo' and payload#>>'{order,booking_source}'='zalo'),2,'Unrelated edit preserves original source');
select is((select count(*)::int from email_payloads where payload#>>'{previous_order,players_count}'='4' and payload#>>'{order,players_count}'='6'),2,'Players compare complete old and new values');
select is((select count(*)::int from email_payloads where payload->>'event_type'='ticket_updated'),2,'Modification is never mislabeled as new booking');
select ok(not has_function_privilege('anon','public.booking_email_managed(uuid)','EXECUTE'),'Anonymous callers cannot probe snapshots');
select ok(not has_function_privilege('authenticated','public.booking_email_managed(uuid)','EXECUTE'),'Players cannot probe snapshots');
delete from net.http_request_queue where url='https://example.invalid/email-test';
set constraints all deferred;
insert into public.sessions(id,owner_id,name,date,start_time,duration_minutes,max_players,arena_count,session_type,visibility,status,booking_type,venue_key)
values('86000000-0000-4000-8000-000000000004','86000000-0000-4000-8000-000000000003','Session only',current_date+302,'16:00',30,4,1,'coop','public','open','community','ha-do-centrosa');
set constraints all immediate;
select is((select count(*)::int from email_payloads),1,'Session without order sends a creation notification');
select is((select payload#>>'{session,booking_source}' from email_payloads),'website','Player session uses Online source');
delete from net.http_request_queue where url='https://example.invalid/email-test';
set constraints all deferred;
update public.sessions set status='cancelled' where id='86000000-0000-4000-8000-000000000004';
set constraints all immediate;
select is((select payload->>'event_type' from email_payloads),'session_cancelled','Cancellation still notifies');
select is((select payload#>>'{previous_session,status}' from email_payloads),'open','Cancellation preserves old confirmation status');
delete from net.http_request_queue where url='https://example.invalid/email-test';
update public.sessions set updated_at=now() where id='86000000-0000-4000-8000-000000000004';
select is((select count(*)::int from email_payloads),0,'Timestamp-only updates do not send mail');
select * from finish();
rollback;
